using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class InspectCustomRoots {public static object Main(){var rows=new List<object>();string root="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/";foreach(var id in new[]{"CH01","CH02"})foreach(var file in new[]{"body","throw","charge","dribble"}){var g=AssetDatabase.LoadAssetAtPath<GameObject>(root+id+"/"+file+".fbx");if(g==null)continue;foreach(var t in g.GetComponentsInChildren<Transform>(true).Where(t=>t==g.transform||t.name=="Armature"||t.name=="Hips")){rows.Add(new{id,file,path=AnimationUtility.CalculateTransformPath(t,g.transform),position=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},euler=new[]{t.localEulerAngles.x,t.localEulerAngles.y,t.localEulerAngles.z},scale=new[]{t.localScale.x,t.localScale.y,t.localScale.z}});}}return new{items=rows};}}
